// -------------------------------------------------
// Dedup + keyword extraction + priority mapping
// -------------------------------------------------
// Uses n8n static data to remember which Todoist task
// IDs have already been synced, so the same task is
// never imported twice even though we poll on a timer.
// -------------------------------------------------

const tasks = $input.all();
const staticData = $getWorkflowStaticData('global');

// Initialize the synced-IDs set if this is the first run
if (!staticData.syncedIds) {
  staticData.syncedIds = [];
}

// Keep only tasks we haven't synced yet
const newTasks = tasks.filter(t => {
  const tid = String(t.json.id);
  return !staticData.syncedIds.includes(tid);
});

if (newTasks.length === 0) {
  // No new tasks — stop the workflow gracefully
  throw new Error('NO_NEW_TASKS');
}

// Process each new task and mark as synced
const output = newTasks.map(t => {
  const task = t.json;
  const tid = String(task.id);

  // Mark as synced immediately
  staticData.syncedIds.push(tid);

  // Keep only last 500 IDs to avoid memory bloat
  if (staticData.syncedIds.length > 500) {
    staticData.syncedIds = staticData.syncedIds.slice(-500);
  }

  // --- Keyword extraction for epic matching ---
  const taskName = task.content || '';
  const parts = taskName.split(/[:\-\u2013\u2014]/);
  const firstPart = parts[0].trim();
  const words = firstPart.split(/\s+/);
  const keyword = words.slice(0, 2).join(' ');

  // --- Priority mapping (Todoist → Notion) ---
  const priorityMap = { 4: 'Urgent', 3: 'High', 2: 'Medium', 1: 'Low' };

  return {
    keyword: keyword || taskName,
    taskId: tid,
    taskName: taskName,
    taskDescription: task.description || '',
    taskPriority: priorityMap[task.priority] || 'Medium',
    taskUrl: task.url || '',
    todoistPriority: task.priority
  };
});

return output;
